-- 095: the gaps left after 088-094, from Carter's follow-up screenshots,
-- 2026-10-31. Big One's opening (28 May 1994); Big Loop's (1983); Ferrari Land's Red Force
-- (Intamin LSM launch) and Junior Red Force (SBF Visa Race Coaster MX611; RCDB
-- gives only speed); Madrid's Tornado (Intamin suspended looper -> "Intamin
-- Invert") and Vertigo (MACK Wilde Maus Compact; SBNO since Jul 2025, not
-- marked closed).
-- Relocation linked: Speedy Bob (Bobbejaanland) -> Vertigo (Madrid, home), as
-- Vertigo's page lists. Speedy Bob still has no closing date - none was shown.
-- Safe to run twice.
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 3, json_object('id', id, 'fields', json_array('yr', 'opened', 'openedPrec'), 'via', '095') FROM coasters WHERE name = 'Big One' AND park = 'Pleasure Beach Resort' AND yr IS NULL;
UPDATE coasters SET yr = 1994, opened = '1994-05-28', openedPrec = 'day' WHERE name = 'Big One' AND park = 'Pleasure Beach Resort' AND yr IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 9, json_object('id', id, 'fields', json_array('manu', 'model', 'h', 's', 'l', 'inv', 'yr', 'opened', 'openedPrec'), 'via', '095') FROM coasters WHERE name = 'Red Force' AND park = 'Ferrari Land' AND l IS NULL;
UPDATE coasters SET manu = 'Intamin', model = 'Intamin Launch', h = 367.3, s = 111.8, l = 2887.2, inv = 0, yr = 2017, opened = '2017-04-07', openedPrec = 'day' WHERE name = 'Red Force' AND park = 'Ferrari Land' AND l IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 7, json_object('id', id, 'fields', json_array('manu', 'model', 's', 'inv', 'yr', 'opened', 'openedPrec'), 'via', '095') FROM coasters WHERE name = 'Junior Red Force' AND park = 'Ferrari Land' AND manu IS NULL;
UPDATE coasters SET manu = 'SBF Visa', model = 'SBF Visa Race Coaster', s = 28.0, inv = 0, yr = 2018, opened = '2018-05-22', openedPrec = 'day' WHERE name = 'Junior Red Force' AND park = 'Ferrari Land' AND manu IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 10, json_object('id', id, 'fields', json_array('manu', 'model', 'h', 's', 'l', 'inv', 'dur', 'yr', 'opened', 'openedPrec'), 'via', '095') FROM coasters WHERE name = 'Tornado' AND park = 'Parque de Atracciones de Madrid' AND l IS NULL;
UPDATE coasters SET manu = 'Intamin', model = 'Intamin Invert', h = 98.0, s = 49.7, l = 2624.7, inv = 3, dur = 120, yr = 1999, opened = '1999-05-23', openedPrec = 'day' WHERE name = 'Tornado' AND park = 'Parque de Atracciones de Madrid' AND l IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 10, json_object('id', id, 'fields', json_array('manu', 'model', 'h', 's', 'l', 'inv', 'dur', 'yr', 'opened', 'openedPrec'), 'via', '095') FROM coasters WHERE name = 'Vértigo' AND park = 'Parque de Atracciones de Madrid' AND l IS NULL;
UPDATE coasters SET manu = 'MACK Rides', model = 'MACK Wild Mouse', h = 45.9, s = 28.0, l = 1213.9, inv = 0, dur = 85, yr = 2009, opened = '2009-05-15', openedPrec = 'day' WHERE name = 'Vértigo' AND park = 'Parque de Atracciones de Madrid' AND l IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 3, json_object('id', id, 'fields', json_array('yr', 'opened', 'openedPrec'), 'via', '095') FROM coasters WHERE name = 'Big Loop' AND park = 'Heide Park Resort' AND yr IS NULL;
UPDATE coasters SET yr = 1983, opened = '1983', openedPrec = 'year' WHERE name = 'Big Loop' AND park = 'Heide Park Resort' AND yr IS NULL;
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT c.id, h.id FROM coasters c, coasters h WHERE h.name = 'Vértigo' AND h.park = 'Parque de Atracciones de Madrid' AND (c.id = h.id OR (c.name = 'Speedy Bob' AND c.park = 'Bobbejaanland'));
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'same_ride_set', h.name, (SELECT COUNT(*) FROM same_ride s WHERE s.ride = h.id), json_object('ride', h.id, 'at', (SELECT json_group_array(json_object('id', c.id, 'park', c.park, 'name', c.name)) FROM coasters c JOIN same_ride s ON s.coaster = c.id WHERE s.ride = h.id), 'via', '095') FROM coasters h WHERE h.name = 'Vértigo' AND h.park = 'Parque de Atracciones de Madrid' AND (SELECT COUNT(*) FROM same_ride s WHERE s.ride = h.id) > 1 AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'same_ride_set' AND a.detail LIKE '%"via":"095"%' AND json_extract(a.detail, '$.ride') = h.id);
